        self.assistant = assistant
        self.listener = listener
        self.messages = assistant.init_messages()
        self.override_params = None

    def process_input(self, user_input, args):
        if user_input.startswith(':q'):
            return False
        elif user_input.startswith(':c'):
            self.messages = self.assistant.init_messages()
            self.listener.on_chat_clear()
            return True
        elif user_input.startswith(':r'):
            if self.messages:
                self.listener.on_chat_rerun(True)
                self._process_chat(self.messages[-1], self.override_params)
            else:
                self.listener.on_chat_rerun(False)
            return True
        else:
            self.override_params = {k: v for k, v in args.items() if k in self.assistant.supported_overrides()}
            self._process_chat(user_input, self.override_params)
            return True

    def _process_chat(self, user_input, override_params):
        user_message = {'role': 'user', 'content': user_input}
        self.listener.on_chat_message(user_message)
        self.messages.append(user_message)
        try:
            with self.listener.response_streamer() as streamer:
                for event in self.assistant.complete_chat(self.messages, override_params):
                    if isinstance(event, MessageDeltaEvent):
                        streamer.on_next_token(event.text)
                    elif isinstance(event, UsageEvent):
                        self.listener.on_usage_event(event)
        except CompletionError as e:
            self.listener.on_error(e)
        else:
            assistant_message = {'role': 'assistant', 'content': streamer.get_response()}
            self.listener.on_chat_message(assistant_message)
