            with V.parsing(additional_properties=False):
                self._testValidation(get_schema(),
                                     valid=values[:2], invalid=values[2:])
            self._testValidation(get_schema(),
                                 valid=values[:4], invalid=values[4:])

        if V.Object.REQUIRED_PROPERTIES:
